int intersections = 0;
std::mt19937 gen(std::random_device{}());
std::uniform_real_distribution<double> dist(-1.0, 1.0);

for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction vector
    double dx = dist(gen);
    double dy = dist(gen);
    double dz = dist(gen);

    // Avoid zero direction vector
    if (dx == 0 && dy == 0 && dz == 0) {
        dx = 1.0;
    }

    // Create ray from point p in random direction
    CGALRay ray(p.toEigenVector(), CGALPoint(p.x() + dx, p.y() + dy, p.z() + dz));

    // Count intersections with the AABB tree
    std::vector<CGALTriangle> intersectionsList;
    tree.all_intersected_primitives(ray, std::back_inserter(intersectionsList));

    // Each intersection counts as one crossing
    intersections += intersectionsList.size();
}

// Point is inside if odd number of intersections (ray casting rule)
return intersections % 2 == 1;

